do $$declare definition text;begin select pg_get_functiondef('public.twitter_complete_analytics_item(uuid,text,text,jsonb,timestamptz,integer,text,text,text,jsonb)'::regprocedure)into definition;execute replace(definition,'select * into i from public.twitter_analytics_items where id=a.item_id for update;select wr.*','select * into i from public.twitter_analytics_items where id=a.item_id for update;if i.status in(''succeeded'',''failed'',''cancelled'')then raise exception using errcode=''55000'',message=''Item de analytics já possui resultado terminal.'';end if;select wr.*');end$$;
